<?php declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('PUT'); requireAdmin(); safeApi(function():void{$db=apiDatabase();$id=requestId();$i=jsonRequest();$fields=['code','title','description','discount_type','discount_value','min_order_amount','max_discount','start_date','expiry_date','usage_limit','per_user_limit','status'];$set=[];$p=[':id'=>$id];foreach($fields as $f)if(array_key_exists($f,$i)){$set[]="$f=:$f";$p[":$f"]=$i[$f];}if(!$set)jsonResponse(false,'No fields to update.',null,[],422);$s=$db->prepare('UPDATE coupons SET '.implode(',',$set).' WHERE id=:id');$s->execute($p);if(!$s->rowCount())jsonResponse(false,'Coupon not found or unchanged.',null,[],404);jsonResponse(true,'Coupon updated.');});
